-- F02 staff identities. Tenant boundaries apply to every identity row.
CREATE TABLE identity_staff (id uuid NOT NULL, tenant_id uuid NOT NULL REFERENCES tenant(id), created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, email text, mobile text, password_hash text NOT NULL, role text NOT NULL, active boolean NOT NULL, professional_grant boolean NOT NULL, mfa_secret text, version bigint NOT NULL, PRIMARY KEY (tenant_id, id));
ALTER TABLE identity_staff ENABLE ROW LEVEL SECURITY;
ALTER TABLE identity_staff FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON identity_staff USING (tenant_id = NULLIF(current_setting('app.tenant_id', true),'')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true),'')::uuid);
GRANT SELECT,INSERT,UPDATE,DELETE ON identity_staff TO ${application_role};
CREATE TABLE identity_session (id uuid NOT NULL, tenant_id uuid NOT NULL REFERENCES tenant(id), created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, account_id uuid NOT NULL, kind text NOT NULL, refresh_hash text NOT NULL, device_label text NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz, generation bigint NOT NULL, PRIMARY KEY (tenant_id, id));
ALTER TABLE identity_session ENABLE ROW LEVEL SECURITY;
ALTER TABLE identity_session FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON identity_session USING (tenant_id = NULLIF(current_setting('app.tenant_id', true),'')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true),'')::uuid);
GRANT SELECT,INSERT,UPDATE,DELETE ON identity_session TO ${application_role};
CREATE TABLE identity_refresh_history (id uuid NOT NULL, tenant_id uuid NOT NULL REFERENCES tenant(id), created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, session_id uuid NOT NULL, credential_hash text NOT NULL, PRIMARY KEY (tenant_id, id));
ALTER TABLE identity_refresh_history ENABLE ROW LEVEL SECURITY;
ALTER TABLE identity_refresh_history FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON identity_refresh_history USING (tenant_id = NULLIF(current_setting('app.tenant_id', true),'')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true),'')::uuid);
GRANT SELECT,INSERT,DELETE ON identity_refresh_history TO ${application_role};
CREATE TABLE identity_mfa_challenge (id uuid NOT NULL, tenant_id uuid NOT NULL REFERENCES tenant(id), created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, account_id uuid NOT NULL, session_id uuid, purpose text NOT NULL, credential_hash text NOT NULL, pending_secret text, device_label text NOT NULL, expires_at timestamptz NOT NULL, attempts integer NOT NULL, consumed_at timestamptz, PRIMARY KEY (tenant_id, id));
ALTER TABLE identity_mfa_challenge ENABLE ROW LEVEL SECURITY;
ALTER TABLE identity_mfa_challenge FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON identity_mfa_challenge USING (tenant_id = NULLIF(current_setting('app.tenant_id', true),'')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true),'')::uuid);
GRANT SELECT,INSERT,UPDATE,DELETE ON identity_mfa_challenge TO ${application_role};
CREATE TABLE identity_mfa_step (id uuid NOT NULL, tenant_id uuid NOT NULL REFERENCES tenant(id), created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, account_id uuid NOT NULL, step bigint NOT NULL, PRIMARY KEY (tenant_id, id));
ALTER TABLE identity_mfa_step ENABLE ROW LEVEL SECURITY;
ALTER TABLE identity_mfa_step FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON identity_mfa_step USING (tenant_id = NULLIF(current_setting('app.tenant_id', true),'')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true),'')::uuid);
GRANT SELECT,INSERT,DELETE ON identity_mfa_step TO ${application_role};
CREATE TABLE identity_rate_bucket (id uuid NOT NULL, tenant_id uuid NOT NULL REFERENCES tenant(id), created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, dimension text NOT NULL, key_hash text NOT NULL, window_start timestamptz NOT NULL, attempts integer NOT NULL, PRIMARY KEY (tenant_id, id));
ALTER TABLE identity_rate_bucket ENABLE ROW LEVEL SECURITY;
ALTER TABLE identity_rate_bucket FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON identity_rate_bucket USING (tenant_id = NULLIF(current_setting('app.tenant_id', true),'')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true),'')::uuid);
GRANT SELECT,INSERT,UPDATE,DELETE ON identity_rate_bucket TO ${application_role};
CREATE TABLE identity_guard (id uuid NOT NULL, tenant_id uuid NOT NULL REFERENCES tenant(id), created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, PRIMARY KEY (tenant_id, id));
ALTER TABLE identity_guard ENABLE ROW LEVEL SECURITY;
ALTER TABLE identity_guard FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON identity_guard USING (tenant_id = NULLIF(current_setting('app.tenant_id', true),'')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true),'')::uuid);
GRANT SELECT,INSERT,UPDATE ON identity_guard TO ${application_role};

ALTER TABLE identity_staff ADD CONSTRAINT staff_identifier_required CHECK(email IS NOT NULL OR mobile IS NOT NULL), ADD CONSTRAINT staff_role CHECK(role IN ('OWNER','MANAGER','RECEPTIONIST','PROFESSIONAL','ACCOUNTANT'));
CREATE UNIQUE INDEX identity_staff_email ON identity_staff(tenant_id,email) WHERE email IS NOT NULL;
CREATE UNIQUE INDEX identity_staff_mobile ON identity_staff(tenant_id,mobile) WHERE mobile IS NOT NULL;
ALTER TABLE identity_session ADD CONSTRAINT session_staff FOREIGN KEY(tenant_id,account_id) REFERENCES identity_staff(tenant_id,id);
ALTER TABLE identity_refresh_history ADD CONSTRAINT refresh_session FOREIGN KEY(tenant_id,session_id) REFERENCES identity_session(tenant_id,id) ON DELETE CASCADE;
ALTER TABLE identity_mfa_challenge ADD CONSTRAINT challenge_staff FOREIGN KEY(tenant_id,account_id) REFERENCES identity_staff(tenant_id,id), ADD CONSTRAINT challenge_session FOREIGN KEY(tenant_id,session_id) REFERENCES identity_session(tenant_id,id);
ALTER TABLE identity_mfa_step ADD CONSTRAINT step_staff FOREIGN KEY(tenant_id,account_id) REFERENCES identity_staff(tenant_id,id);
CREATE UNIQUE INDEX identity_step_once ON identity_mfa_step(tenant_id,account_id,step);
CREATE UNIQUE INDEX identity_rate_key ON identity_rate_bucket(tenant_id,dimension,key_hash);
CREATE UNIQUE INDEX identity_one_guard ON identity_guard(tenant_id);
CREATE INDEX identity_sessions_account ON identity_session(tenant_id,account_id);
CREATE INDEX identity_refresh_lookup ON identity_refresh_history(tenant_id,session_id,credential_hash);
CREATE INDEX identity_challenge_account ON identity_mfa_challenge(tenant_id,account_id);

ALTER TABLE identity_session ADD COLUMN mfa_verified boolean NOT NULL;
